function calculateErgoRoi() {
  const price = parseFloat(document.getElementById('productPrice').value) || 0;
  const years = parseFloat(document.getElementById('lifespanYears').value) || 1;
  const hours = parseFloat(document.getElementById('dailyHours').value) || 1;
  const therapy = parseFloat(document.getElementById('monthlyTherapy').value) || 0;
  const reliefRate = parseFloat(document.getElementById('reliefRate').value) || 0;

  const totalDays = years * 365;
  const costPerDay = Math.round(price / totalDays);
  const costPerHour = Math.round((costPerDay / hours) * 10) / 10;

  const monthlySaved = therapy * reliefRate;
  const annualSaved = monthlySaved * 12;
  const totalSaved = annualSaved * years;
  const netCost = price - totalSaved;

  let paybackText = '';
  let headline = '';
  if (monthlySaved > 0) {
    const paybackMonths = Math.ceil(price / monthlySaved);
    const paybackYears = (paybackMonths / 12).toFixed(1);
    if (paybackMonths <= years * 12) {
      paybackText = paybackMonths + 'ヶ月（約' + paybackYears + '年）';
      if (netCost <= 0) {
        headline = '約' + paybackYears + '年で完全回収！整体代節約で実質プラス +' + Math.abs(netCost).toLocaleString() + '円 の黒字';
      } else {
        headline = '1日たった約' + costPerDay + '円。約' + paybackYears + '年で元が取れます';
      }
    } else {
      paybackText = paybackMonths + 'ヶ月（' + paybackYears + '年）';
      headline = '耐用年数内の全額回収には届きませんが、日割りコストはわずか' + costPerDay + '円です';
    }
  } else {
    paybackText = '節約額なし';
    headline = '1日あたり' + costPerDay + '円（1時間 ' + costPerHour + '円）で利用可能';
  }

  const resultBox = document.getElementById('calcResult');
  resultBox.innerHTML = '<div class="result-headline">結論：<strong>' + headline + '</strong></div>' +
    '<div class="metrics-row">' +
      '<div class="metric-card"><span>1日あたりのコスト</span><strong>約 ' + costPerDay.toLocaleString() + ' 円</strong><small>缶コーヒー1本以下の水準</small></div>' +
      '<div class="metric-card"><span>1時間あたりのコスト</span><strong>約 ' + costPerHour + ' 円</strong><small>1日' + hours + '時間利用時</small></div>' +
      '<div class="metric-card"><span>元が取れる期間（回収目安）</span><strong>' + paybackText + '</strong><small>整体代の削減のみで試算</small></div>' +
      '<div class="metric-card"><span>' + years + '年間の実質負担額</span><strong>' + (netCost <= 0 ? '実質 0 円（黒字）' : netCost.toLocaleString() + ' 円') + '</strong><small>' + (netCost <= 0 ? '整体代削減が購入費を上回る' : '定価より' + totalSaved.toLocaleString() + '円お得') + '</small></div>' +
    '</div>';
}
document.addEventListener('DOMContentLoaded', calculateErgoRoi);
